-- The month (1 to 12) the sheet's fiscal years start in; 1 (January) unless set.
ALTER TABLE sheet ADD COLUMN fiscal_start_month INTEGER NOT NULL DEFAULT 1 CHECK (fiscal_start_month BETWEEN 1 AND 12);
    /**
     * The days after its to-date an open period is left open: once its to-date plus these is before the sheet's
     * today, it is closed. Null (blank) for off.
     */
    @Column(name = "grace_days")
    private Integer graceDays;

    /** The pot shared among the members of each balanced pool by their shares. Null (blank) for none. Not dated. */
    @Column(name = "pot")
    private BigDecimal pot;

    /** The month (1 to 12) the sheet's fiscal years start in; 1 unless set. Not dated. */
    @Column(name = "fiscal_start_month", nullable = false)
    private int fiscalStartMonth = 1;

    /**
     * The id of the sheet's parent sheet, whose rates apply to a grade with no rate in force on a date on this sheet;
     * null for none. Not dated.
     */
    @Column(name = "parent_id")
    private String parentId;

    /**
     * The sheet as it stood at the end of the day, for figures taken as of it: the day stands in for its today, and
     * its dated settings are the values recorded while its today was on or before the day (for each key and from-date
     * the last one so recorded). Not to be saved.
     */
    public Sheet asOf(LocalDate day) {
        Sheet then = new Sheet();
        then.id = id;
        then.createdAt = createdAt;
        then.today = day;
        then.permissions.putAll(permissions);
        then.policyDate = policyDate;
        then.periodNumberingFrom = periodNumberingFrom;
        then.entryDate = entryDate;
        then.graceDays = graceDays;
        then.pot = pot;
        then.fiscalStartMonth = fiscalStartMonth;
        then.parentId = parentId;
        then.archived = archived;
        then.lastSettleBatch = lastSettleBatch;
        // a value recorded before changes were kept stands as it is
        for (DatedSetting s : settings) {
            if (settingChanges.stream()
                    .noneMatch(c -> c.getKey().equals(s.getKey()) && c.getFrom().equals(s.getFrom()))) {
                then.settings.add(s);

    public Integer getGraceDays() {
        return graceDays;
    }

    public void setGraceDays(Integer graceDays) {
        this.graceDays = graceDays;
    }

    public BigDecimal getPot() {
        return pot;
    }

    public void setPot(BigDecimal pot) {
        this.pot = pot;
    }

    public int getFiscalStartMonth() {
        return fiscalStartMonth;
    }

    /** The fiscal year FY<year> the date falls in: the one starting on the first of the fiscal start month in that year. */
    public int fiscalYearOf(LocalDate date) {
        return date.getMonthValue() >= fiscalStartMonth ? date.getYear() : date.getYear() - 1;
    }

    public record PeriodNumberingFromForm(LocalDate value) {
    }

    /** The entry date as the form submits it: a date, or null for blank (off). */
    public record EntryDateForm(LocalDate value) {
    }

    /** The pot as the form submits it: 0.00 or more with up to two decimals, or null for blank (none). */
    public record PotForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value) {
    }

    /** The fiscal start month as the form submits it: 1 to 12. */
    public record FiscalStartMonthForm(@NotNull @Min(1) @Max(12) Integer value) {
    }

    /** The parent sheet as the form submits it: a sheet id, or null for blank (none). */
    @PutMapping("/settings/grace-days")
    public SettingsView setGraceDays(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody GraceDaysForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setGraceDays(user, sheetId, form.value()));
    }

    @PutMapping("/settings/pot")
    public SettingsView setPot(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PotForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setPot(user, sheetId, form.value()));
    }

    @PutMapping("/settings/fiscal-start-month")
    public SettingsView setFiscalStartMonth(
    public Sheet setGraceDays(String by, String sheetId, Integer days) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setGraceDays(days);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=grace-days value="
                + (days == null ? "" : days.toString()));
        return saved;
    }

    /**
     * Sets the sheet's pot (null for blank: none): shared among the members of each balanced pool by their shares.
     * Not dated.
     */
    @Transactional
    public Sheet setPot(String by, String sheetId, BigDecimal pot) {
        BigDecimal scaled = pot == null ? null : pot.setScale(2, RoundingMode.UNNECESSARY);
        Sheet sheet = sheets.lock(sheetId);
        sheet.setPot(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=pot value="
                + (scaled == null ? "" : scaled.toPlainString()));
        return saved;
    }

    /** Sets the month (1 to 12) the sheet's fiscal years start in. Not dated. */
    @Transactional
    public Sheet setFiscalStartMonth(String by, String sheetId, int month) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setFiscalStartMonth(month);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=fiscal-start-month value="
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can clone the sheet.");
        }
        sheetService.lock(sheetId);
        if (sheetId.equals(toSheetId) || sheets.existsById(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet must be one never used.");
        }
        claims.flush();
        try {
            jdbc.update("INSERT INTO sheet (id, created_at, today, policy_date, period_numbering_from, entry_date,"
                    + " grace_days, pot, parent_id, fiscal_start_month) SELECT ?, CURRENT_TIMESTAMP, today, policy_date,"
                    + " period_numbering_from, entry_date, grace_days, pot, parent_id, fiscal_start_month FROM sheet"
                    + " WHERE id = ?",
                    toSheetId, sheetId);
        } catch (DataIntegrityViolationException e) {
            // another user started it at the same moment
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet must be one never used.");

